'use strict';
function reachesConsensus(votes, threshold) {
  const tally = {};
  for (const v of votes) tally[v] = (tally[v] || 0) + 1;
  const top = Math.max(0, ...Object.values(tally));
  return top >= threshold;
}
module.exports = { reachesConsensus };

'use strict';
function applyDefaults(config, defaults) {
  const out = Object.assign({}, defaults);
  for (const key of Object.keys(config || {})) {
    if (config[key] !== undefined) out[key] = config[key];
  }
  return out;
}
module.exports = { applyDefaults };

'use strict';
const VALID_EVENTS = ['preStart', 'postStart', 'preStop', 'postStop'];
function registerHook(registry, event, handler) {
  if (!VALID_EVENTS.includes(event)) {
    throw new Error('unknown lifecycle event: ' + event);
  }
  (registry[event] = registry[event] || []).push(handler);
  return registry;
}
module.exports = { registerHook, VALID_EVENTS };

'use strict';
function mergeLayers(layers) {
  return layers.reduce((acc, layer) => Object.assign(acc, layer || {}), {});
}
module.exports = { mergeLayers };

'use strict';
function interpretExit(code) {
  if (code === 0) return 'success';
  if (code === 2) return 'blocked';
  return 'error';
}
function isSuccess(code) {
  return code === 0;
}
module.exports = { interpretExit, isSuccess };

'use strict';
function walkIncludes(root, resolve) {
  const visited = [];
  const seen = new Set();
  const queue = [root];
  while (queue.length) {
    const node = queue.shift();
    if (seen.has(node)) continue;
    seen.add(node);
    visited.push(node);
    for (const inc of resolve(node) || []) queue.push(inc);
  }
  return visited;
}
module.exports = { walkIncludes };

'use strict';
function splitStreams(combined) {
  const lines = String(combined).split('\n');
  const stdout = [];
  const stderr = [];
  for (const line of lines) {
    if (line.startsWith('[stderr] ')) stderr.push(line.slice(9));
    else stdout.push(line);
  }
  return { stdout: stdout.join('\n'), stderr: stderr.join('\n') };
}
module.exports = { splitStreams };

'use strict';
const path = require('path');
function toPortablePath(input) {
  return String(input).split(path.sep).join('/');
}
function stripWorkspace(input, workspace) {
  const abs = path.resolve(input);
  return abs.startsWith(workspace) ? abs.slice(workspace.length).replace(/^\/+/, '') : abs;
}
module.exports = { toPortablePath, stripWorkspace };
